python - <<'PY'
import json,numpy as np
for s in ['013_sandal_pregrasp','014_sandal_lower','015_sandal_close','016_sandal_lift_check','017_sandal_carry_raise','019_return_to_rack_2']:
 m=json.load(open('/app/output/runs/'+s+'/meta.json'))
 c=m['cameras']['robot_r1:zed_link:Camera:0']; E=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);
 # target position from current assumed fixed, project to camera
 for name,p in [('target', [0.345,3.629,0.07]),('shoe', [0.345,3.629,0.0])]:
  v=E[:,:3]@p+E[:,3]; uv=K@v; uv=uv[:2]/uv[2];
  print(s,name,'uv',uv,'depth',v[2])
 print('proprio',m.get('proprio',{}).get('now',[])[:3], 'camera',c['extrinsic_cv'][0])
PY

