import json,numpy as np
m=json.load(open('/app/output/runs/021_turn_toward_rack/meta.json')); c=m['cameras']['robot_r1:zed_link:Camera:0']; E=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3];print('C',C); p=np.array(m['proprio']['now']); print('base',p[28:35]);print('left',p[35:42]);print('right',p[42:49])
for uv in [(45,30),(60,30),(70,50),(45,55),(85,50),(60,70),(75,80)]:
 ray=R.T@np.linalg.inv(K)@np.array([*uv,1.]);
 for z in [0.5,0.7]:
  t=(z-C[2])/ray[2]; print(uv,z,np.round(C+t*ray,3))
